// Validate and clean input
const body = $input.item.json.body || $input.item.json;

if (!body.keyword || body.keyword.trim() === '') {
  throw new Error('keyword is required');
}

const keyword = body.keyword.trim();
const depth = body.depth && !isNaN(parseInt(body.depth)) ? parseInt(body.depth) : 20;

// Ensure depth is within reasonable bounds
const validDepth = Math.max(1, Math.min(depth, 100));

return {
  keyword: keyword,
  depth: validDepth,
  timestamp: new Date().toISOString()
};

// Extract and structure SERP data
const serpData = $input.item.json;
const organicResults = serpData.organic_results || [];
const relatedSearches = serpData.related_searches || [];

// Extract SERP overview
const serpOverview = organicResults.map((result, index) => {
  const url = result.link || '';
  const domain = url ? new URL(url).hostname.replace('www.', '') : '';

  return {
    rank: index + 1,
    title: result.title || '',
    snippet: result.snippet || '',
    link: url,
    domain: domain,
    displayed_link: result.displayed_link || domain
  };
});

// Calculate domain authority distribution (simple heuristic)
const domainCounts = {};
serpOverview.forEach(item => {
  domainCounts[item.domain] = (domainCounts[item.domain] || 0) + 1;
});

const highAuthorityDomains = ['wikipedia.org', 'youtube.com', 'amazon.com', 'facebook.com', 
  'linkedin.com', 'twitter.com', 'instagram.com', 'pinterest.com', 'reddit.com'];

const authorityCount = serpOverview.filter(item => 
  highAuthorityDomains.some(domain => item.domain.includes(domain))
).length;

return {
  serpOverview: serpOverview,
  relatedSearches: relatedSearches.map(rs => rs.query || ''),
  authorityMetrics: {
    highAuthorityCount: authorityCount,
    uniqueDomains: Object.keys(domainCounts).length,
    totalResults: serpOverview.length
  }
};

// Process related keywords data
const relatedData = $input.item.json;
const serpOverview = $('Process SERP Data').item.json.serpOverview;
const relatedSearches = relatedData.related_searches || [];
const relatedQuestions = relatedData.related_questions || [];

// Extract related keywords with available metrics
const relatedKeywords = [];

// Add related searches
relatedSearches.forEach(item => {
  if (item.query) {
    relatedKeywords.push({
      keyword: item.query,
      source: 'related_search',
      volume: null,
      cpc: null,
      difficulty: null
    });
  }
});

// Add related questions (People Also Ask)
relatedQuestions.forEach(item => {
  if (item.question) {
    relatedKeywords.push({
      keyword: item.question,
      source: 'people_also_ask',
      volume: null,
      cpc: null,
      difficulty: null,
      snippet: item.snippet || null
    });
  }
});

return {
  relatedKeywords: relatedKeywords,
  serpOverview: serpOverview
};

// Merge SERP and Related Keywords data
const serpData = $('Process SERP Data').item.json;
const relatedData = $('Process Related Keywords').item.json;
const validatedInput = $('Validate Input').item.json;

return {
  keyword: validatedInput.keyword,
  depth: validatedInput.depth,
  timestamp: validatedInput.timestamp,
  serpOverview: serpData.serpOverview,
  relatedSearches: serpData.relatedSearches,
  authorityMetrics: serpData.authorityMetrics,
  relatedKeywords: relatedData.relatedKeywords
};

// Content Gap Analysis
const data = $input.item.json;
const serpOverview = data.serpOverview || [];
const relatedKeywords = data.relatedKeywords || [];

// Extract all titles and snippets
const allContent = serpOverview.map(item => `${item.title} ${item.snippet}`).join(' ').toLowerCase();

// Common topic words to analyze
const topicKeywords = data.keyword.toLowerCase().split(' ');

// Analyze content themes
const contentThemes = {};
serpOverview.forEach(item => {
  const content = `${item.title} ${item.snippet}`.toLowerCase();

  // Look for common patterns
  const patterns = [
    { name: 'how-to', keywords: ['how to', 'guide', 'tutorial', 'step', 'learn'] },
    { name: 'comparison', keywords: ['vs', 'versus', 'compare', 'best', 'top', 'review'] },
    { name: 'pricing', keywords: ['price', 'cost', 'pricing', 'cheap', 'expensive', 'affordable'] },
    { name: 'definition', keywords: ['what is', 'definition', 'meaning', 'explain'] },
    { name: 'list', keywords: ['list', 'types', 'kinds', 'examples'] },
    { name: 'location', keywords: ['near me', 'location', 'where', 'local'] },
    { name: 'reviews', keywords: ['review', 'rating', 'testimonial', 'customer'] },
    { name: 'benefits', keywords: ['benefit', 'advantage', 'why', 'reason'] }
  ];

  patterns.forEach(pattern => {
    if (pattern.keywords.some(kw => content.includes(kw))) {
      contentThemes[pattern.name] = (contentThemes[pattern.name] || 0) + 1;
    }
  });
});

// Identify gaps (themes with low coverage)
const totalResults = serpOverview.length;
const missingSubtopics = [];
const thinContentAreas = [];

const allThemes = ['how-to', 'comparison', 'pricing', 'definition', 'list', 'location', 'reviews', 'benefits'];
allThemes.forEach(theme => {
  const count = contentThemes[theme] || 0;
  const coverage = totalResults > 0 ? (count / totalResults) * 100 : 0;

  if (coverage === 0) {
    missingSubtopics.push({
      theme: theme,
      coverage: 0,
      opportunity: 'high'
    });
  } else if (coverage < 20) {
    thinContentAreas.push({
      theme: theme,
      coverage: coverage.toFixed(1),
      opportunity: 'medium'
    });
  }
});

// Identify repeated competitor angles
const repeatedAngles = Object.entries(contentThemes)
  .filter(([_, count]) => count >= totalResults * 0.5)
  .map(([theme, count]) => ({
    theme: theme,
    frequency: count,
    saturation: 'high'
  }));

// Generate content opportunities
const contentOpportunities = [];

if (missingSubtopics.length > 0) {
  missingSubtopics.forEach(gap => {
    contentOpportunities.push(`Create ${gap.theme} content - no competitors covering this angle`);
  });
}

if (thinContentAreas.length > 0) {
  thinContentAreas.forEach(thin => {
    contentOpportunities.push(`Expand on ${thin.theme} content - low competition (${thin.coverage}% coverage)`);
  });
}

// Add opportunities from related keywords
const uniqueQuestions = relatedKeywords.filter(kw => kw.source === 'people_also_ask');
if (uniqueQuestions.length > 0) {
  contentOpportunities.push(`Answer ${uniqueQuestions.length} related questions from People Also Ask`);
}

return {
  ...data,
  contentGaps: {
    missingSubtopics: missingSubtopics,
    thinContentAreas: thinContentAreas,
    repeatedCompetitorAngles: repeatedAngles,
    contentOpportunities: contentOpportunities,
    contentThemes: contentThemes
  }
};

