// Parse AI response and merge with data
const data = $('Gap Analysis').item.json;
const aiResponse = $input.item.json;

// Extract the AI message content
let intentData;
try {
  const content = aiResponse.message?.content || aiResponse.text || JSON.stringify(aiResponse);

  // Try to extract JSON from markdown code blocks if present
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/) || [null, content];
  const jsonStr = jsonMatch[1].trim();

  intentData = JSON.parse(jsonStr);
} catch (e) {
  // Fallback intent data
  intentData = {
    primary_intent: 'Mixed',
    intent_confidence: {
      informational: 50,
      commercial: 30,
      transactional: 15,
      navigational: 5
    },
    reasoning: 'Unable to parse AI response, using default classification'
  };
}

return {
  ...data,
  searchIntent: intentData
};

// Calculate Difficulty and Opportunity Scores
const data = $input.item.json;
const serpOverview = data.serpOverview || [];
const authorityMetrics = data.authorityMetrics || {};
const contentGaps = data.contentGaps || {};
const searchIntent = data.searchIntent || {};

// === DIFFICULTY SCORE (0-100, higher = harder) ===
let difficultyScore = 0;

// 1. Domain Authority Factor (0-40 points)
const highAuthorityRatio = authorityMetrics.highAuthorityCount / (authorityMetrics.totalResults || 1);
difficultyScore += highAuthorityRatio * 40;

// 2. Domain Diversity Factor (0-20 points)
const domainDiversity = authorityMetrics.uniqueDomains / (authorityMetrics.totalResults || 1);
if (domainDiversity > 0.8) {
  difficultyScore += 5; // High diversity = easier
} else if (domainDiversity < 0.5) {
  difficultyScore += 20; // Low diversity = dominated by few sites
} else {
  difficultyScore += 10;
}

// 3. Content Saturation (0-20 points)
const saturatedThemes = (contentGaps.repeatedCompetitorAngles || []).length;
difficultyScore += Math.min(saturatedThemes * 5, 20);

// 4. Intent Competition (0-20 points)
const intentScores = searchIntent.intent_confidence || {};
if (intentScores.transactional > 60) {
  difficultyScore += 20; // Transactional = high competition
} else if (intentScores.informational > 60) {
  difficultyScore += 10; // Informational = medium competition
} else {
  difficultyScore += 15;
}

// Cap difficulty score
difficultyScore = Math.min(Math.round(difficultyScore), 100);

// === OPPORTUNITY SCORE (0-100, higher = better opportunity) ===
let opportunityScore = 0;

// 1. Content Gap Bonus (0-40 points)
const missingTopics = (contentGaps.missingSubtopics || []).length;
const thinAreas = (contentGaps.thinContentAreas || []).length;
opportunityScore += Math.min(missingTopics * 10 + thinAreas * 5, 40);

// 2. Keyword Expansion Potential (0-25 points)
const relatedKeywordCount = (data.relatedKeywords || []).length;
opportunityScore += Math.min(relatedKeywordCount * 1.25, 25);

// 3. Intent Alignment (0-20 points)
if (searchIntent.primary_intent === 'Informational' || searchIntent.primary_intent === 'Commercial') {
  opportunityScore += 20; // Good for content marketing
} else if (searchIntent.primary_intent === 'Mixed') {
  opportunityScore += 15;
} else {
  opportunityScore += 10;
}

// 4. Competition Weakness (0-15 points)
if (difficultyScore < 40) {
  opportunityScore += 15; // Low difficulty = high opportunity
} else if (difficultyScore < 60) {
  opportunityScore += 10;
} else {
  opportunityScore += 5;
}

// Cap opportunity score
opportunityScore = Math.min(Math.round(opportunityScore), 100);

// === PRIORITY CLASSIFICATION ===
let priority = 'Low';
const combinedScore = opportunityScore - (difficultyScore * 0.7);

if (combinedScore > 30 && opportunityScore > 60) {
  priority = 'High';
} else if (combinedScore > 10 && opportunityScore > 40) {
  priority = 'Medium';
}

return {
  ...data,
  difficultyScore: difficultyScore,
  opportunityScore: opportunityScore,
  priority: priority,
  scoreBreakdown: {
    difficulty_factors: {
      domain_authority: Math.round(highAuthorityRatio * 40),
      domain_diversity: domainDiversity > 0.8 ? 5 : (domainDiversity < 0.5 ? 20 : 10),
      content_saturation: Math.min(saturatedThemes * 5, 20),
      intent_competition: intentScores.transactional > 60 ? 20 : (intentScores.informational > 60 ? 10 : 15)
    },
    opportunity_factors: {
      content_gaps: Math.min(missingTopics * 10 + thinAreas * 5, 40),
      keyword_expansion: Math.min(relatedKeywordCount * 1.25, 25),
      intent_alignment: searchIntent.primary_intent === 'Informational' || searchIntent.primary_intent === 'Commercial' ? 20 : 10,
      competition_weakness: difficultyScore < 40 ? 15 : (difficultyScore < 60 ? 10 : 5)
    }
  }
};

