// Parse clustering response and merge
const data = $('Score Difficulty & Opportunity').item.json;
const aiResponse = $input.item.json;

let clusterData;
try {
  const content = aiResponse.message?.content || aiResponse.text || JSON.stringify(aiResponse);

  // Try to extract JSON from markdown code blocks if present
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/) || [null, content];
  const jsonStr = jsonMatch[1].trim();

  clusterData = JSON.parse(jsonStr);
} catch (e) {
  // Fallback cluster data
  clusterData = {
    clusters: [
      {
        topic_name: 'Primary Topic',
        keywords: [data.keyword],
        primary_keyword: data.keyword,
        secondary_keywords: data.relatedKeywords.slice(0, 3).map(k => k.keyword),
        recommended_page_type: 'guide',
        content_angle: 'Comprehensive guide covering all aspects'
      }
    ]
  };
}

return {
  ...data,
  keywordClusters: clusterData.clusters || []
};

// Build Final SCO Report
const data = $input.item.json;

// Assemble the complete report
const scoReport = {
  keyword: data.keyword,
  search_intent: {
    primary: data.searchIntent.primary_intent || 'Mixed',
    confidence_scores: data.searchIntent.intent_confidence || {},
    reasoning: data.searchIntent.reasoning || ''
  },
  difficulty_score: data.difficultyScore,
  opportunity_score: data.opportunityScore,
  priority: data.priority,
  score_breakdown: data.scoreBreakdown || {},
  serp_overview: data.serpOverview || [],
  content_gaps: {
    missing_subtopics: data.contentGaps.missingSubtopics || [],
    thin_content_areas: data.contentGaps.thinContentAreas || [],
    repeated_competitor_angles: data.contentGaps.repeatedCompetitorAngles || [],
    content_opportunities: data.contentGaps.contentOpportunities || [],
    content_themes: data.contentGaps.contentThemes || {}
  },
  keyword_clusters: data.keywordClusters || [],
  related_keywords: data.relatedKeywords || [],
  metadata: {
    search_depth: data.depth,
    total_serp_results: data.serpOverview.length,
    total_related_keywords: data.relatedKeywords.length,
    total_clusters: data.keywordClusters.length,
    authority_metrics: data.authorityMetrics || {},
    timestamp: data.timestamp
  }
};

return scoReport;
